const rows = $input.all().map(item => item.json);

// 1. Separate Google Sheets records
const taskRows = rows.filter(row => row['Task ID']);
const raidRows = rows.filter(row => row['RAID ID']);
const changeRows = rows.filter(row => row['Change ID']);
const stakeholderRows = rows.filter(row => row['Stakeholder ID']);

// 2. Validate all four data sources
if (taskRows.length === 0) {
  throw new Error('No Tasks found in Google Sheets');
}

if (raidRows.length === 0) {
  throw new Error('No RAID records found in Google Sheets');
}

if (changeRows.length === 0) {
  throw new Error('No Change Requests found in Google Sheets');
}

if (stakeholderRows.length === 0) {
  throw new Error('No Stakeholders found in Google Sheets');
}

// 3. Prepare Tasks
const tasks = taskRows.map(row => ({
  id: String(row['Task ID']).trim(),
  name: row['Task Name'] || '',
  owner: row['Owner'] || '',
  startDate: row['Start Date'] || '',
  due: row['Due Date'] || '',
  status: String(row['Status'] || '').trim(),
  priority: row['Priority'] || '',
  dependency: row['Dependency'] || '',
  lastUpdated: row['Last Updated'] || '',
  baselineStatus: row['Baseline Status'] || '',
  alertStatus: row['Alert Status'] || '',
  rowNumber: row.row_number
}));

// 4. Prepare all RAID records
const raid = raidRows.map(row => ({
  id: String(row['RAID ID']).trim(),
  type: String(row['Type'] || '').trim(),
  description: row['Description'] || '',
  probability: row['Probability'] || '',
  impact: row['Impact'] || '',
  score: row['Score'] || '',
  responseAction: row['Response / Action'] || '',
  owner: row['Owner'] || '',
  reviewDate: row['Review Date'] || '',
  status: String(row['Status'] || '').trim(),
  sourceEvidence: row['Source / Evidence'] || '',
  priority: '',
  rowNumber: row.row_number
}));

// 5. Prepare Change Requests
const changes = changeRows.map(row => ({
  id: String(row['Change ID']).trim(),
  title: row['Change Title'] || '',
  description: row['Description'] || '',
  requestedBy: row['Requested By'] || '',
  dateSubmitted: row['Date Submitted'] || '',
  impactOnScope: row['Impact on Scope'] || '',
  impactOnSchedule: row['Impact on Schedule'] || '',
  impactOnCost: row['Impact on Cost'] || '',
  recommendation: row['Recommended Option'] || '',
  status: String(row['Approval Status'] || '').trim(),
  decisionOwner: row['Decision Owner'] || '',
  decisionDate: row['Decision Date'] || '',
  rowNumber: row.row_number
}));

// 6. Prepare Stakeholders
const stakeholders = stakeholderRows.map(row => ({
  id: String(row['Stakeholder ID']).trim(),
  name: row['Name'] || '',
  role: row['Role'] || '',
  email: String(row['Email'] || '').trim(),
  communicationType: row['Communication Type'] || '',
  frequency: row['Frequency'] || '',
  preferredChannel: row['Preferred Channel'] || '',
  lastContactDate: row['Last Contact Date'] || '',
  nextUpdateDate: row['Next Update Date'] || '',
  communicationStatus: row['Communication Status'] || '',
  rowNumber: row.row_number
}));

// 7. Build project object
const project = {
  referenceDate: '2026-04-14',
  tasks,
  raid,
  changes,
  stakeholders
};

// 8. Return structured project data
return [{
  json: {
    project,
    results: [],
    dataSources: {
      tasks: 'Google Sheets',
      raid: 'Google Sheets',
      changes: 'Google Sheets',
      stakeholders: 'Google Sheets'
    },
    dataValidation: {
      taskCount: tasks.length,
      raidCount: raid.length,
      changeCount: changes.length,
      stakeholderCount: stakeholders.length,
      riskCount: raid.filter(
        r => r.type.toLowerCase() === 'risk'
      ).length
    }
  }
}];

const d=$input.first().json; const ref=new Date(d.project.referenceDate+'T00:00:00Z');
const overdue=d.project.tasks.filter(t=>t.due && t.status && !['done','completed','closed'].includes(t.status.toLowerCase()) && new Date(t.due+'T00:00:00Z')<ref);
const missingStatus=d.project.tasks.filter(t=>!t.status).map(t=>t.id);
d.results.push({automation:'Schedule Monitoring',overdue,missingStatus,note:'Missing status is unknown, not automatically overdue'});
return [{json:d}];

const d=$input.first().json; const contacts=d.project.stakeholders.map(s=>({id:s.id,name:s.name,emailConfigured:!!s.email}));
d.results.push({automation:'Stakeholder Communication',contacts,draftPreview:'Trailhead Mobile: Release readiness update — CR-01 pending sponsor decision. This is a DEMO DRAFT only.',action:'Preview only; no email sent'});
return [{json:d}];

const d=$input.first().json; const pending=d.project.changes.filter(c=>/pending|open|review/i.test(c.status));
d.results.push({automation:'Change Request Tracking',pending,action:'Escalation recommended; no approvals or project data changed'});
return [{json:d}];

const d = $input.first().json;

// Select open Risks only
const open = d.project.raid.filter(r =>
  String(r.type || '').trim().toLowerCase() === 'risk' &&
  /\bopen\b/i.test(String(r.status || ''))
);

// Use documented actions from Google Sheets
const recommendations = open.map(r =>
  `${r.id}: ${r.responseAction || 'No documented response action'}`
);

d.results.push({
  automation: 'AI Risk Management',
  openRisks: open,
  recommendations,
  note: 'Rule-based analysis using real Google Sheets RAID data. Gemini is not connected yet.'
});

return [{ json: d }];

const d=$input.first().json; const pending=d.project.changes.filter(c=>!/approved|rejected|closed/i.test(c.status));
d.results.push({automation:'Project Closure',ready:false,blockers:[...pending.map(c=>c.id+' unresolved'), 'iOS and Android release acceptance not confirmed','Task statuses incomplete'],action:'Readiness report only; never close automatically'});
return [{json:d}];

const d = $input.first().json;

const byName = Object.fromEntries(
  d.results.map(r => [r.automation, r])
);

const summary = {
  project: 'Trailhead Mobile',
  mode: 'DEMO PROCESSING + AUTOMATION LOG',
  referenceDate: d.project.referenceDate,
  branches: d.results.length,

  unknownTaskStatuses:
    byName['Schedule Monitoring'].missingStatus,

  openRisks:
    byName['AI Risk Management'].openRisks.length,

  pendingChanges:
    byName['Change Request Tracking'].pending.map(c => c.id),

  closureReady:
    byName['Project Closure'].ready,

  emailsSent: 0,
  projectDataWrites: 0,

  logWriteStatus:
    'Handled by downstream Google Sheets node',

  aiStatus:
    d.aiStatus || 'Gemini analysis unavailable'
};

return [{
  json: {
    summary,
    results: d.results,

    logPreview: {
      'Workflow Name': 'Trailhead Mobile – AI & Automation',
      Action: 'Demo run',
      Result:
        d.aiStatus === 'Gemini analysis completed successfully'
          ? 'Completed five demo branches and Gemini AI risk analysis'
          : 'Completed five demo branches; Gemini analysis unavailable',
      'Error Message': '',
      note: 'Prepared for Automation Log. Actual write occurs in the next Google Sheets node.'
    }
  }
}];

const gemini = $input.first().json;

// Read Gemini's response
const rawText =
  gemini.content?.parts?.find(p => typeof p.text === 'string')?.text
  ?? gemini.text
  ?? gemini.output;

if (!rawText) {
  throw new Error('Gemini response text was not found');
}

// Remove Markdown code fences
const cleanText = rawText
  .replace(/^\s*```(?:json)?\s*/i, '')
  .replace(/\s*```\s*$/, '')
  .trim();

const analysis = JSON.parse(cleanText);

// Restore original project data
const data = JSON.parse(
  JSON.stringify($('05 AI Risk Management').first().json)
);

const riskResult = data.results.find(
  r => r.automation === 'AI Risk Management'
);

if (!riskResult) {
  throw new Error('Risk Management result not found');
}

// Validate the five risk IDs
const expectedIds = riskResult.openRisks.map(r => r.id);
const aiRisks = analysis.risks;

if (
  !Array.isArray(aiRisks) ||
  aiRisks.length !== expectedIds.length ||
  new Set(aiRisks.map(r => r.id)).size !== expectedIds.length ||
  !expectedIds.every(id => aiRisks.some(r => r.id === id))
) {
  throw new Error('Gemini risk IDs do not match the source data');
}

// Attach AI analysis without replacing original data
riskResult.aiAnalysis = aiRisks.map(r => ({
  id: r.id,
  assessment: r.assessment,
  nextAction: r.nextAction,
  sponsorEscalation: r.sponsorEscalation
}));

riskResult.note =
  'Rule-based risk identification with Gemini AI recommendations. Advisory only; no decisions or records modified.';

data.aiStatus = 'Gemini analysis completed successfully';

return [{ json: data }];
